import { DriverPackageNotInstalledError, TypeORMError } from "../../error"
import type { QueryRunner } from "../../query-runner/QueryRunner"
import { AbstractSqliteDriver } from "../sqlite-abstract/AbstractSqliteDriver"
import type { ExpoDataSourceOptions } from "./ExpoDataSourceOptions"
import { ExpoQueryRunner } from "./ExpoQueryRunner"

export class ExpoDriver extends AbstractSqliteDriver {
    declare options: ExpoDataSourceOptions

    constructor(dataSource: DataSource) {
        super(dataSource)

        // load the sqlite module — either the explicitly provided driver
        // override or the auto-loaded `expo-sqlite` package.
        this.loadDependencies()
    }

    async disconnect(): Promise<void> {
        this.queryRunner = undefined
        await this.databaseConnection.closeAsync()
        this.databaseConnection = undefined
    }

    createQueryRunner(): QueryRunner {
        this.queryRunner ??= new ExpoQueryRunner(this)

        return this.queryRunner
    }

    protected async createDatabaseConnection() {
        this.databaseConnection = await this.sqlite.openDatabaseAsync(
            this.options.database,
        )
        await this.databaseConnection.runAsync("PRAGMA foreign_keys = ON")
        return this.databaseConnection
    }

    /**
     * Resolves the SQLite module. When a `driver` override is supplied in the
     * options it is validated and used as-is; otherwise the `expo-sqlite`
     * package is loaded via `requireExpoSqlite()`.
     */
    protected loadDependencies(): void {
        if (this.options.driver !== undefined) {
            // An explicit override was provided — it must expose the modern
            // async API introduced in Expo SDK v52.
            if (!("openDatabaseAsync" in this.options.driver)) {
                throw new TypeORMError(
                    "The Expo driver's custom overrides must match the " +
                        "expo-sqlite module shape (it must expose " +
                        "`openDatabaseAsync`).",
                )
            }

            this.sqlite = this.options.driver
            return
        }

        let sqlite: any
        try {
            sqlite = this.requireExpoSqlite()
        } catch (err: any) {
            if (err?.code === "MODULE_NOT_FOUND") {
                // A MODULE_NOT_FOUND can either mean expo-sqlite itself is not
                // installed, or that one of its transitive dependencies is
                // missing. Only the former should be reported as a missing
                // driver package — otherwise re-throw the original error so the
                // real cause is not masked.
                const firstLine = String(err.message ?? "").split("\n")[0]
                if (firstLine.includes("expo-sqlite")) {
                    throw new DriverPackageNotInstalledError(
                        "Expo",
                        "expo-sqlite",
                    )
                }
            }

            throw err
        }

        if (!("openDatabaseAsync" in sqlite)) {
            throw new TypeORMError(
                "The installed expo-sqlite version is not supported. " +
                    "Please upgrade to Expo SDK v52 or later, which provides " +
                    "the `openDatabaseAsync` API.",
            )
        }

        this.sqlite = sqlite
    }

    /**
     * Loads the `expo-sqlite` module. Extracted into its own method so that
     * subclasses can override module resolution (e.g. for testing).
     */
    protected requireExpoSqlite(): unknown {
        return require("expo-sqlite")
    }
}
