import type { API, FileInfo, ObjectProperty, Property } from "jscodeshift"
import { getStringValue } from "../ast-helpers"

export const name = path.basename(__filename, path.extname(__filename))
export const description =
    "remove redundant `driver: require(\"expo-sqlite\")` from Expo DataSource options"

// Returns the string key name for a Property/ObjectProperty, handling both
// identifier keys (`driver:`) and string-literal keys (`"driver":`).
const propKeyName = (prop: Property | ObjectProperty): string | null =>
    prop.key.type === "Identifier" ? prop.key.name : getStringValue(prop.key)

// Matches a plain `require("expo-sqlite")` call expression — not a member
// access (`require("expo-sqlite").default`), an identifier/variable, or a
// require of a different package. This ensures we only drop the property when
// its value is exactly the module the driver now auto-loads.
const isExpoSqliteRequire = (node: {
    type: string
    callee?: { type: string; name?: string }
    arguments?: unknown[]
}): boolean => {
    if (node.type !== "CallExpression") return false
    if (node.callee?.type !== "Identifier" || node.callee.name !== "require") {
        return false
    }
    const args = node.arguments ?? []
    if (args.length !== 1) return false
    return getStringValue(args[0] as any) === "expo-sqlite"
}

export const datasourceExpo = (file: FileInfo, api: API) => {
    const j = api.jscodeshift
    const root = j(file.source)

    let hasChanges = false

    // Scope to ObjectExpressions that look like TypeORM Expo DataSource
    // options — they carry both `type: "expo"` and a sibling `database`
    // property. Requiring `database` avoids false positives on unrelated
    // `{ type: "expo" }` objects.
    root.find(j.ObjectExpression).forEach((objPath) => {
        let isExpo = false
        let hasDatabase = false

        for (const prop of objPath.node.properties) {
            if (prop.type !== "Property" && prop.type !== "ObjectProperty") {
                continue
            }
            const keyName = propKeyName(prop)
            if (keyName === "type" && getStringValue(prop.value) === "expo") {
                isExpo = true
            } else if (keyName === "database") {
                hasDatabase = true
            }
        }

        if (!isExpo || !hasDatabase) return

        const original = objPath.node.properties.length
        objPath.node.properties = objPath.node.properties.filter((prop) => {
            if (prop.type !== "Property" && prop.type !== "ObjectProperty") {
                return true
            }
            if (propKeyName(prop) !== "driver") return true
            return !isExpoSqliteRequire(prop.value as any)
        })

        if (objPath.node.properties.length !== original) {
            hasChanges = true
        }
    })

    return hasChanges ? root.toSource() : undefined
}

export const fn = datasourceExpo
export default fn
